use std::embedded_curve_ops::{EmbeddedCurvePoint, EmbeddedCurveScalar, fixed_base_scalar_mul};
use shared::{EncryptedCard, remask, assert_valid_permutation, elgamal_encrypt, priv_to_pub_key, compute_reveal_token};

global DECK_SIZE: u32 = 52;

/// Proves that a player correctly shuffled and re-encrypted the deck.
/// The player applies a secret permutation and fresh randomness to each card.
///
/// Public inputs: the deck before and after shuffle, plus the aggregate public key.
/// Private inputs: the permutation and randomness values.
fn main(
    // Public inputs: deck before shuffle (flattened as coordinate pairs)
    deck_in_c1_x: pub [Field; DECK_SIZE],
    deck_in_c1_y: pub [Field; DECK_SIZE],
    deck_in_c2_x: pub [Field; DECK_SIZE],
    deck_in_c2_y: pub [Field; DECK_SIZE],
    // Public inputs: deck after shuffle
    deck_out_c1_x: pub [Field; DECK_SIZE],
    deck_out_c1_y: pub [Field; DECK_SIZE],
    deck_out_c2_x: pub [Field; DECK_SIZE],
    deck_out_c2_y: pub [Field; DECK_SIZE],
    // Public input: aggregate public key
    aggregate_pk_x: pub Field,
    aggregate_pk_y: pub Field,
    // Private inputs
    permutation: [u32; DECK_SIZE],
    randomness: [Field; DECK_SIZE],
) {
    let aggregate_pk = EmbeddedCurvePoint {
        x: aggregate_pk_x,
        y: aggregate_pk_y,
        is_infinite: false,
    };

    // 1. Verify the permutation is valid (each index 0..N-1 appears exactly once)
    assert_valid_permutation(permutation);

    // 2. Verify each card was correctly permuted and re-encrypted
    for i in 0..DECK_SIZE {
        assert(randomness[i] != 0, "Randomness must be non-zero");
        let source_idx = permutation[i];

        // Reconstruct the source card from public inputs
        let source_card = EncryptedCard {
            c1: EmbeddedCurvePoint {
                x: deck_in_c1_x[source_idx],
                y: deck_in_c1_y[source_idx],
                is_infinite: false,
            },
            c2: EmbeddedCurvePoint {
                x: deck_in_c2_x[source_idx],
                y: deck_in_c2_y[source_idx],
                is_infinite: false,
            },
        };

        // Apply remask with this card's randomness
        let expected = remask(source_card, randomness[i], aggregate_pk);

        // Verify output matches
        assert(deck_out_c1_x[i] == expected.c1.x, "Shuffle C1.x mismatch");
        assert(deck_out_c1_y[i] == expected.c1.y, "Shuffle C1.y mismatch");
        assert(deck_out_c2_x[i] == expected.c2.x, "Shuffle C2.x mismatch");
        assert(deck_out_c2_y[i] == expected.c2.y, "Shuffle C2.y mismatch");
    }
}

#[test]
fn test_shuffle_encrypt_full_deck() {
    // Two-player setup
    let sk1: Field = 3;
    let sk2: Field = 7;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let apk = pk1 + pk2;

    // Encrypt 52 cards with APK
    let mut deck_in_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let card_scalar = (i as Field) + 1;
        let r = (i as Field) + 100;
        let encrypted = elgamal_encrypt(apk, card_scalar, r);
        deck_in_c1_x[i] = encrypted.c1.x;
        deck_in_c1_y[i] = encrypted.c1.y;
        deck_in_c2_x[i] = encrypted.c2.x;
        deck_in_c2_y[i] = encrypted.c2.y;
    }

    // Simple permutation: reverse the deck
    let mut permutation: [u32; DECK_SIZE] = [0; DECK_SIZE];
    for i in 0..DECK_SIZE {
        permutation[i] = (DECK_SIZE - 1 - i) as u32;
    }

    // Fresh randomness for remask
    let mut rand: [Field; DECK_SIZE] = [0; DECK_SIZE];
    for i in 0..DECK_SIZE {
        rand[i] = (i as Field) + 200;
    }

    // Compute expected output deck
    let mut deck_out_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let src = permutation[i];
        let source_card = EncryptedCard {
            c1: EmbeddedCurvePoint {
                x: deck_in_c1_x[src],
                y: deck_in_c1_y[src],
                is_infinite: false,
            },
            c2: EmbeddedCurvePoint {
                x: deck_in_c2_x[src],
                y: deck_in_c2_y[src],
                is_infinite: false,
            },
        };
        let remasked = remask(source_card, rand[i], apk);
        deck_out_c1_x[i] = remasked.c1.x;
        deck_out_c1_y[i] = remasked.c1.y;
        deck_out_c2_x[i] = remasked.c2.x;
        deck_out_c2_y[i] = remasked.c2.y;
    }

    // Run the circuit
    main(
        deck_in_c1_x, deck_in_c1_y, deck_in_c2_x, deck_in_c2_y,
        deck_out_c1_x, deck_out_c1_y, deck_out_c2_x, deck_out_c2_y,
        apk.x, apk.y,
        permutation, rand,
    );
}

#[test]
fn test_shuffle_identity_permutation() {
    // Identity permutation: cards stay in same order, only re-encrypted
    let sk1: Field = 5;
    let sk2: Field = 9;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let apk = pk1 + pk2;

    let mut deck_in_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_in_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let encrypted = elgamal_encrypt(apk, (i as Field) + 1, (i as Field) + 500);
        deck_in_c1_x[i] = encrypted.c1.x;
        deck_in_c1_y[i] = encrypted.c1.y;
        deck_in_c2_x[i] = encrypted.c2.x;
        deck_in_c2_y[i] = encrypted.c2.y;
    }

    // Identity permutation: [0, 1, 2, ..., 51]
    let mut permutation: [u32; DECK_SIZE] = [0; DECK_SIZE];
    for i in 0..DECK_SIZE {
        permutation[i] = i as u32;
    }

    let mut rand: [Field; DECK_SIZE] = [0; DECK_SIZE];
    for i in 0..DECK_SIZE {
        rand[i] = (i as Field) + 1000;
    }

    let mut deck_out_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_out_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let source_card = EncryptedCard {
            c1: EmbeddedCurvePoint { x: deck_in_c1_x[i], y: deck_in_c1_y[i], is_infinite: false },
            c2: EmbeddedCurvePoint { x: deck_in_c2_x[i], y: deck_in_c2_y[i], is_infinite: false },
        };
        let remasked = remask(source_card, rand[i], apk);
        deck_out_c1_x[i] = remasked.c1.x;
        deck_out_c1_y[i] = remasked.c1.y;
        deck_out_c2_x[i] = remasked.c2.x;
        deck_out_c2_y[i] = remasked.c2.y;
    }

    main(
        deck_in_c1_x, deck_in_c1_y, deck_in_c2_x, deck_in_c2_y,
        deck_out_c1_x, deck_out_c1_y, deck_out_c2_x, deck_out_c2_y,
        apk.x, apk.y,
        permutation, rand,
    );
}

#[test]
fn test_shuffle_preserves_decryption() {
    // After shuffle, decrypting a card should yield the correct original value
    let sk1: Field = 3;
    let sk2: Field = 7;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let apk = pk1 + pk2;

    // Encrypt 52 cards
    let mut deck_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut deck_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let encrypted = elgamal_encrypt(apk, (i as Field) + 1, (i as Field) + 100);
        deck_c1_x[i] = encrypted.c1.x;
        deck_c1_y[i] = encrypted.c1.y;
        deck_c2_x[i] = encrypted.c2.x;
        deck_c2_y[i] = encrypted.c2.y;
    }

    // Shuffle: move card 0 to position 51 (swap first and last)
    let mut permutation: [u32; DECK_SIZE] = [0; DECK_SIZE];
    permutation[0] = (DECK_SIZE - 1) as u32; // position 0 gets card 51
    for i in 1..DECK_SIZE - 1 {
        permutation[i] = i as u32; // middle cards stay
    }
    permutation[DECK_SIZE - 1] = 0; // position 51 gets card 0

    let mut rand: [Field; DECK_SIZE] = [0; DECK_SIZE];
    for i in 0..DECK_SIZE {
        rand[i] = (i as Field) + 300;
    }

    // Compute output deck
    let mut out_c1_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut out_c1_y: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut out_c2_x: [Field; DECK_SIZE] = [0; DECK_SIZE];
    let mut out_c2_y: [Field; DECK_SIZE] = [0; DECK_SIZE];

    for i in 0..DECK_SIZE {
        let src = permutation[i];
        let source_card = EncryptedCard {
            c1: EmbeddedCurvePoint { x: deck_c1_x[src], y: deck_c1_y[src], is_infinite: false },
            c2: EmbeddedCurvePoint { x: deck_c2_x[src], y: deck_c2_y[src], is_infinite: false },
        };
        let remasked = remask(source_card, rand[i], apk);
        out_c1_x[i] = remasked.c1.x;
        out_c1_y[i] = remasked.c1.y;
        out_c2_x[i] = remasked.c2.x;
        out_c2_y[i] = remasked.c2.y;
    }

    // Verify circuit passes
    main(
        deck_c1_x, deck_c1_y, deck_c2_x, deck_c2_y,
        out_c1_x, out_c1_y, out_c2_x, out_c2_y,
        apk.x, apk.y,
        permutation, rand,
    );

    // Verify card at position 0 (originally card 51, scalar=52) decrypts correctly
    let card_c1 = EmbeddedCurvePoint { x: out_c1_x[0], y: out_c1_y[0], is_infinite: false };
    let card_c2 = EmbeddedCurvePoint { x: out_c2_x[0], y: out_c2_y[0], is_infinite: false };
    let token1 = compute_reveal_token(sk1, card_c1);
    let token2 = compute_reveal_token(sk2, card_c1);
    let decrypted = card_c2 - token1 - token2;

    // Card 51 has scalar = 52
    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(52));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

