use std::embedded_curve_ops::{
    EmbeddedCurvePoint, EmbeddedCurveScalar, multi_scalar_mul, fixed_base_scalar_mul,
};

/// An encrypted card: two curve points (C1, C2) representing an ElGamal ciphertext.
/// C1 = r * G, C2 = m * G + r * PK
pub struct EncryptedCard {
    pub c1: EmbeddedCurvePoint,
    pub c2: EmbeddedCurvePoint,
}

// ============================================================
// Key operations
// ============================================================

/// Derive public key from secret key: pk = sk * G
pub fn priv_to_pub_key(secret_key: Field) -> EmbeddedCurvePoint {
    let sk = EmbeddedCurveScalar::from_field(secret_key);
    fixed_base_scalar_mul(sk)
}

// ============================================================
// ElGamal encryption (exponential form)
// ============================================================

/// Encrypt a card index using exponential ElGamal.
/// card_scalar should be (card_index + 1) to avoid point at infinity.
/// Returns (r*G, card_scalar*G + r*PK)
pub fn elgamal_encrypt(
    public_key: EmbeddedCurvePoint,
    card_scalar: Field,
    randomness: Field,
) -> EncryptedCard {
    let r = EmbeddedCurveScalar::from_field(randomness);
    let m = EmbeddedCurveScalar::from_field(card_scalar);

    // C1 = r * G
    let c1 = fixed_base_scalar_mul(r);

    // C2 = m * G + r * PK  (single multi-scalar-mul for efficiency)
    let c2 = multi_scalar_mul(
        [EmbeddedCurvePoint::generator(), public_key],
        [m, r],
    );

    EncryptedCard { c1, c2 }
}

// ============================================================
// Remask: re-randomize an encrypted card
// ============================================================

/// Re-randomize an encrypted card with fresh randomness.
/// new_C1 = C1 + r * G
/// new_C2 = C2 + r * APK
pub fn remask(
    card: EncryptedCard,
    randomness: Field,
    aggregate_pk: EmbeddedCurvePoint,
) -> EncryptedCard {
    let r = EmbeddedCurveScalar::from_field(randomness);
    let one = EmbeddedCurveScalar::from_field(1);

    // new_C1 = 1 * C1 + r * G  (single MSM)
    let new_c1 = multi_scalar_mul(
        [card.c1, EmbeddedCurvePoint::generator()],
        [one, r],
    );

    // new_C2 = 1 * C2 + r * APK  (single MSM)
    let new_c2 = multi_scalar_mul(
        [card.c2, aggregate_pk],
        [one, r],
    );

    EncryptedCard { c1: new_c1, c2: new_c2 }
}

// ============================================================
// Reveal token: partial decryption
// ============================================================

/// Compute reveal token: token = sk * C1
pub fn compute_reveal_token(
    secret_key: Field,
    c1: EmbeddedCurvePoint,
) -> EmbeddedCurvePoint {
    let sk = EmbeddedCurveScalar::from_field(secret_key);
    multi_scalar_mul([c1], [sk])
}

// ============================================================
// Permutation validation
// ============================================================

/// Assert that `perm` is a valid permutation of [0, 1, ..., N-1].
/// Uses sort-and-compare approach.
pub fn assert_valid_permutation<let N: u32>(perm: [u32; N]) {
    let sorted = perm.sort();
    for i in 0..N {
        assert(sorted[i] == i as u32, "Invalid permutation");
    }
}

// ============================================================
// Tests
// ============================================================

#[test]
fn test_key_generation() {
    let sk: Field = 42;
    let pk = priv_to_pub_key(sk);
    // pk should not be the point at infinity
    assert(!pk.is_infinite);
    // Same secret key should give same public key
    let pk2 = priv_to_pub_key(sk);
    assert(pk.x == pk2.x);
    assert(pk.y == pk2.y);
}

#[test]
fn test_different_keys_different_pubkeys() {
    let pk1 = priv_to_pub_key(1);
    let pk2 = priv_to_pub_key(2);
    assert(pk1.x != pk2.x);
}

#[test]
fn test_elgamal_encrypt_decrypt() {
    let sk: Field = 7;
    let pk = priv_to_pub_key(sk);

    let card_scalar: Field = 5; // card index 4 (encoded as index+1)
    let randomness: Field = 13;

    let encrypted = elgamal_encrypt(pk, card_scalar, randomness);

    // Decrypt: card_point = C2 - sk * C1
    let sk_c1 = compute_reveal_token(sk, encrypted.c1);
    let decrypted = encrypted.c2 - sk_c1;

    // The decrypted point should be card_scalar * G
    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(card_scalar));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

#[test]
fn test_remask_preserves_plaintext() {
    // Encrypt a card, then remask it with fresh randomness.
    // Decrypting the remasked card should yield the same plaintext.
    let sk: Field = 11;
    let pk = priv_to_pub_key(sk);

    let card_scalar: Field = 3;
    let r1: Field = 17;
    let r2: Field = 23;

    let encrypted = elgamal_encrypt(pk, card_scalar, r1);
    let remasked = remask(encrypted, r2, pk);

    // Decrypt remasked card: C2' - sk * C1'
    let sk_c1 = compute_reveal_token(sk, remasked.c1);
    let decrypted = remasked.c2 - sk_c1;

    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(card_scalar));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

#[test]
fn test_aggregate_key_decrypt() {
    // Two players: each has a secret key. The aggregate public key is pk1 + pk2.
    // Encrypt with APK, then each player provides a reveal token.
    let sk1: Field = 5;
    let sk2: Field = 9;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let apk = pk1 + pk2;

    let card_scalar: Field = 7;
    let randomness: Field = 19;

    let encrypted = elgamal_encrypt(apk, card_scalar, randomness);

    // Each player computes their reveal token
    let token1 = compute_reveal_token(sk1, encrypted.c1);
    let token2 = compute_reveal_token(sk2, encrypted.c1);

    // Decrypt: C2 - token1 - token2
    let decrypted = encrypted.c2 - token1 - token2;

    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(card_scalar));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

#[test]
fn test_valid_permutation() {
    assert_valid_permutation([2, 0, 3, 1]);
    assert_valid_permutation([0, 1, 2, 3]);
    assert_valid_permutation([3, 2, 1, 0]);
}

#[test(should_fail)]
fn test_invalid_permutation() {
    assert_valid_permutation([0, 0, 2, 3]); // duplicate 0, missing 1
}


#[test]
fn test_key_from_one() {
    // Edge case: smallest valid secret key
    let pk = priv_to_pub_key(1);
    // pk = 1 * G = G (the generator itself)
    let g = EmbeddedCurvePoint::generator();
    assert(pk.x == g.x);
    assert(pk.y == g.y);
}

#[test]
fn test_encrypt_same_card_different_randomness() {
    // Encrypting the same card with different randomness must produce different ciphertexts
    let pk = priv_to_pub_key(5);
    let enc1 = elgamal_encrypt(pk, 10, 100);
    let enc2 = elgamal_encrypt(pk, 10, 200);
    // C1 must differ (different r * G)
    assert(enc1.c1.x != enc2.c1.x);
    // C2 must also differ
    assert(enc2.c2.x != enc1.c2.x);
}

#[test]
fn test_three_player_aggregate_decrypt() {
    // Three players: encrypt with APK = pk1 + pk2 + pk3, decrypt with all three tokens
    let sk1: Field = 11;
    let sk2: Field = 22;
    let sk3: Field = 33;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let pk3 = priv_to_pub_key(sk3);
    let apk = pk1 + pk2 + pk3;

    let card_scalar: Field = 42;
    let encrypted = elgamal_encrypt(apk, card_scalar, 77);

    let token1 = compute_reveal_token(sk1, encrypted.c1);
    let token2 = compute_reveal_token(sk2, encrypted.c1);
    let token3 = compute_reveal_token(sk3, encrypted.c1);

    let decrypted = encrypted.c2 - token1 - token2 - token3;

    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(card_scalar));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

#[test]
fn test_remask_twice_still_decrypts() {
    // Remask a card twice (simulating 2 shuffle rounds), should still decrypt correctly
    let sk: Field = 13;
    let pk = priv_to_pub_key(sk);

    let card_scalar: Field = 7;
    let encrypted = elgamal_encrypt(pk, card_scalar, 50);
    let remasked1 = remask(encrypted, 60, pk);
    let remasked2 = remask(remasked1, 70, pk);

    let token = compute_reveal_token(sk, remasked2.c1);
    let decrypted = remasked2.c2 - token;

    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(card_scalar));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}

#[test]
fn test_reveal_token_different_per_card() {
    // Reveal tokens for different cards must be different
    let sk: Field = 5;
    let pk = priv_to_pub_key(sk);

    let card_a = elgamal_encrypt(pk, 1, 100);
    let card_b = elgamal_encrypt(pk, 2, 200);

    let token_a = compute_reveal_token(sk, card_a.c1);
    let token_b = compute_reveal_token(sk, card_b.c1);

    // Different C1 means different token
    assert(token_a.x != token_b.x);
}

#[test]
fn test_identity_permutation() {
    assert_valid_permutation([0, 1, 2, 3, 4]);
}

#[test(should_fail)]
fn test_permutation_out_of_range() {
    assert_valid_permutation([0, 1, 2, 99]); // 99 is out of range for N=4
}

#[test(should_fail)]
fn test_permutation_all_zeros() {
    assert_valid_permutation([0, 0, 0, 0]);
}

#[test]
fn test_shuffle_and_remask_preserves_decryption() {
    // Full protocol test with 4 cards and 2 players:
    // 1. Encrypt cards with APK
    // 2. Player 1 shuffles and remaskes
    // 3. Player 2 shuffles and remaskes
    // 4. Decrypt a card using both reveal tokens
    let sk1: Field = 3;
    let sk2: Field = 7;
    let pk1 = priv_to_pub_key(sk1);
    let pk2 = priv_to_pub_key(sk2);
    let apk = pk1 + pk2;

    // Encrypt 4 cards (card_scalar = index + 1)
    let card0 = elgamal_encrypt(apk, 1, 100);
    let card1 = elgamal_encrypt(apk, 2, 101);
    let card2 = elgamal_encrypt(apk, 3, 102);
    let card3 = elgamal_encrypt(apk, 4, 103);

    // Player 1 shuffles: swap 0<->2, 1<->3
    let shuffled0 = remask(card2, 200, apk);
    let shuffled1 = remask(card3, 201, apk);
    let shuffled2 = remask(card0, 202, apk);
    let shuffled3 = remask(card1, 203, apk);

    // Player 2 shuffles: swap 0<->1, 2<->3
    let final0 = remask(shuffled1, 300, apk);
    let _final1 = remask(shuffled0, 301, apk);
    let _final2 = remask(shuffled3, 302, apk);
    let _final3 = remask(shuffled2, 303, apk);

    // After both shuffles, card at position 0 is original card 3 (scalar=4)
    // Permutation: P1=[2,3,0,1] then P2=[1,0,3,2]
    // Position 0: P2 takes from P1's index 1 = card3 (scalar=4)
    let token1 = compute_reveal_token(sk1, final0.c1);
    let token2 = compute_reveal_token(sk2, final0.c1);
    let decrypted = final0.c2 - token1 - token2;

    let expected = fixed_base_scalar_mul(EmbeddedCurveScalar::from_field(4));
    assert(decrypted.x == expected.x);
    assert(decrypted.y == expected.y);
}
